import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import PropTypes from 'prop-types';

/**
 * CustomerNavbar - Navbar สำหรับลูกค้า (ผู้เอาประกัน)
 * แสดง: โลโก้, ชื่อผู้ใช้, การแจ้งเตือน, เมนู
 */
const CustomerNavbar = ({ user }) => {
  const [showNotifications, setShowNotifications] = useState(false);
  const [showUserMenu, setShowUserMenu] = useState(false);

  // TODO: Backend - ดึงการแจ้งเตือนจาก API
  // GET /api/customer/notifications
  const notifications = [
    { id: 1, message: 'อู่ยืนยันรับซ่อมแล้ว', time: '5 นาทีที่แล้ว', read: false },
    { id: 2, message: 'เคลมของคุณได้รับการอนุมัติ', time: '1 ชั่วโมงที่แล้ว', read: false },
    { id: 3, message: 'กรุณาเลือกอู่ซ่อม', time: '2 ชั่วโมงที่แล้ว', read: true },
  ];

  const unreadCount = notifications.filter(n => !n.read).length;

  // TODO: Backend - Logout
  // POST /api/auth/logout
  const handleLogout = () => {
    console.log('Logout - TODO: เชื่อม Backend');
    // localStorage.removeItem('token');
    // navigate('/login');
  };

  return (
    <nav className="bg-white shadow-md sticky top-0 z-40 animate-slide-down">
      <div className="container-custom">
        <div className="flex items-center justify-between h-16">
          
          {/* Logo & Brand */}
          <Link to="/customer/dashboard" className="flex items-center gap-3 group">
            <div className="w-10 h-10 bg-gradient-primary rounded-xl flex items-center justify-center shadow-button group-hover:shadow-glow-primary transition-all duration-300 group-hover:scale-110">
              <span className="material-icons-round text-white text-2xl">
                shield
              </span>
            </div>
            <div>
              <h1 className="text-xl font-bold text-gradient-primary">
                ClaimMate
              </h1>
              <p className="text-xs text-neutral-500">ระบบจัดการเคลมประกัน</p>
            </div>
          </Link>

          {/* Right Menu */}
          <div className="flex items-center gap-4">
            
            {/* Notifications */}
            <div className="relative">
              <button
                onClick={() => setShowNotifications(!showNotifications)}
                className="relative p-2 text-neutral-600 hover:bg-neutral-100 rounded-lg transition-colors duration-300"
              >
                <span className="material-icons-round">notifications</span>
                {unreadCount > 0 && (
                  <span className="absolute top-1 right-1 w-5 h-5 bg-error text-white text-xs font-bold rounded-full flex items-center justify-center animate-bounce-gentle">
                    {unreadCount}
                  </span>
                )}
              </button>

              {/* Notifications Dropdown */}
              {showNotifications && (
                <div className="absolute right-0 mt-2 w-80 bg-white rounded-xl shadow-card-hover border border-neutral-200 animate-slide-down">
                  <div className="p-4 border-b border-neutral-200">
                    <h3 className="font-semibold text-neutral-dark">การแจ้งเตือน</h3>
                  </div>
                  <div className="max-h-96 overflow-y-auto custom-scrollbar">
                    {notifications.length === 0 ? (
                      <div className="p-8 text-center text-neutral-400">
                        <span className="material-icons-round text-5xl mb-2">notifications_none</span>
                        <p>ไม่มีการแจ้งเตือน</p>
                      </div>
                    ) : (
                      notifications.map(notif => (
                        <div
                          key={notif.id}
                          className={`p-4 border-b border-neutral-100 hover:bg-neutral-50 cursor-pointer transition-colors duration-200 ${!notif.read ? 'bg-primary-50' : ''}`}
                        >
                          <p className="text-sm text-neutral-700 mb-1">{notif.message}</p>
                          <p className="text-xs text-neutral-400">{notif.time}</p>
                        </div>
                      ))
                    )}
                  </div>
                  <div className="p-3 border-t border-neutral-200 text-center">
                    <button className="text-sm text-primary-500 hover:text-primary-600 font-medium">
                      ดูทั้งหมด
                    </button>
                  </div>
                </div>
              )}
            </div>

            {/* User Menu */}
            <div className="relative">
              <button
                onClick={() => setShowUserMenu(!showUserMenu)}
                className="flex items-center gap-2 p-2 hover:bg-neutral-100 rounded-lg transition-colors duration-300"
              >
                <div className="w-9 h-9 bg-gradient-secondary rounded-full flex items-center justify-center text-white font-semibold">
                  {user?.name?.charAt(0) || 'U'}
                </div>
                <div className="text-left hidden md:block">
                  <p className="text-sm font-medium text-neutral-dark">
                    {/* TODO: Backend - ดึงข้อมูล user จาก token/session */}
                    {user?.name || 'ผู้ใช้งาน'}
                  </p>
                  <p className="text-xs text-neutral-500">ลูกค้า</p>
                </div>
                <span className="material-icons-round text-neutral-400 text-xl">
                  expand_more
                </span>
              </button>

              {/* User Dropdown */}
              {showUserMenu && (
                <div className="absolute right-0 mt-2 w-56 bg-white rounded-xl shadow-card-hover border border-neutral-200 animate-slide-down">
                  <div className="p-4 border-b border-neutral-200">
                    <p className="font-semibold text-neutral-dark">{user?.name || 'ผู้ใช้งาน'}</p>
                    <p className="text-sm text-neutral-500">{user?.email || 'user@example.com'}</p>
                  </div>
                  <div className="py-2">
                    <Link
                      to="/customer/profile"
                      className="flex items-center gap-3 px-4 py-3 text-neutral-700 hover:bg-neutral-50 transition-colors duration-200"
                    >
                      <span className="material-icons-round text-neutral-400">person</span>
                      <span>โปรไฟล์</span>
                    </Link>
                    <Link
                      to="/customer/settings"
                      className="flex items-center gap-3 px-4 py-3 text-neutral-700 hover:bg-neutral-50 transition-colors duration-200"
                    >
                      <span className="material-icons-round text-neutral-400">settings</span>
                      <span>ตั้งค่า</span>
                    </Link>
                  </div>
                  <div className="border-t border-neutral-200 py-2">
                    <button
                      onClick={handleLogout}
                      className="flex items-center gap-3 px-4 py-3 text-error hover:bg-red-50 transition-colors duration-200 w-full"
                    >
                      <span className="material-icons-round">logout</span>
                      <span>ออกจากระบบ</span>
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </nav>
  );
};

CustomerNavbar.propTypes = {
  user: PropTypes.shape({
    name: PropTypes.string,
    email: PropTypes.string,
    avatar: PropTypes.string,
  }),
};

export default CustomerNavbar;
